set-variable.value:
@{
      var body = context.Request.Body.As<JObject>(preserveContent: true);
      var responses = context.Operation.Id != "chat-completions";
      return __CACHE_DURATION__ > 0
        && context.Request.Headers.GetValueOrDefault("x-ai-cache-bypass", "false") != "true"
        && body != null
        && body.Value<bool?>("stream") != true
        && body.Value<bool?>("background") != true
        && (!responses || (body.Value<bool?>("store") == false
          && (body["previous_response_id"] == null || body["previous_response_id"].Type == JTokenType.Null)
          && (body["conversation"] == null || body["conversation"].Type == JTokenType.Null)));
    }

@{
          var caller = (Jwt)context.Variables["caller"];
          var material = context.Request.Url.ToString() + "\n"
            + caller.Claims.GetValueOrDefault("oid", "") + "\n"
            + context.Request.Headers.GetValueOrDefault("x-agent-name", "") + "\n"
            + context.Request.Headers.GetValueOrDefault("x-routing-mode", "") + "\n"
            + context.Request.Body.As<string>(preserveContent: true);
          return "ai-response-v1-" + Convert.ToBase64String(
            System.Security.Cryptography.SHA256.Create().ComputeHash(
              System.Text.Encoding.UTF8.GetBytes(material)));
        }

@{
          var body = context.Response.Body.As<JObject>(preserveContent: true);
          return body != null
            && (body["error"] == null || body["error"].Type == JTokenType.Null)
            && (context.Operation.Id == "chat-completions"
              || (body.Value<string>("status") == "completed"
                && body.Value<bool?>("store") == false));
        }
